-- JobHistoryRepository.getTotals
select
  "jobName",
  max("queueName") as "queueName",
  sum("succeeded") as "succeeded",
  sum("failed") as "failed",
  sum("retried") as "retried"
from
  "job_run_hourly"
where
  "hour" >= $1
group by
  "jobName"
order by
  "jobName"

