-- JobHistoryRepository.getReasons
select
  "jobName",
  "category",
  "reason",
  count(*) as "count",
  max("createdAt") as "lastAt"
from
  "job_failure_log"
where
  "createdAt" >= $1
group by
  "jobName",
  "category",
  "reason"
order by
  "count" desc,
  "lastAt" desc
limit
  $2

